WHERE c.user_id = #{userId}
AND c.start_time >= #{req.start}
AND c.start_time < #{req.end}

    AND c.title LIKE CONCAT('%', #{req.title}, '%')


    AND c.student_name LIKE CONCAT('%', #{req.studentName}, '%')

AND c.subject = #{req.subject}
AND c.stage = #{req.stage}
AND c.course_type = #{req.courseType}
AND c.organization_id = #{req.organizationId}
AND c.status = #{req.status}

